// frontend/src/components/Navbar.jsx

import React, { useState, useEffect } from "react";
import { NavLink, useNavigate } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { Activity } from "lucide-react";
import TraderSearch from "./TraderSearch";

export default function Navbar() {
  const [scrolled,     setScrolled]     = useState(false);
  const [mobileOpen,   setMobileOpen]   = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const links = [
    { to: "/",             label: "Home"         },
    { to: "/fraud",        label: "Surveillance" },
    { to: "/transactions", label: "Engine"       },
    { to: "/stocks",       label: "Registry"     },
  ];

  return (
    <motion.nav
      initial={{ y: -80, opacity: 0 }}
      animate={{ y: 0,   opacity: 1 }}
      transition={{ duration: 0.6, ease: "easeOut" }}
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled ? "glass border-b border-[#00FF66]/10" : "bg-transparent"
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">

        {/* Logo */}
        <div
          className="flex items-center gap-2 cursor-pointer"
          onClick={() => navigate("/")}
        >
          <Activity className="text-[#00FF66] drop-shadow-neon" size={22} />
          <span className="text-white font-bold text-xl tracking-tight">
            Trace<span className="neon-text">Net</span>
          </span>
        </div>

        {/* Center links */}
        <div className="hidden md:flex items-center gap-1">
          {links.map((l) => (
            <NavLink key={l.to} to={l.to} end style={({ isActive }) => ({})}>
              {({ isActive }) => (
                <span className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 cursor-pointer ${
                  isActive
                    ? "text-[#00FF66] bg-[#00FF66]/10"
                    : "text-gray-400 hover:text-white hover:bg-white/5"
                }`}>
                  {l.label}
                </span>
              )}
            </NavLink>
          ))}
        </div>

        {/* Right side */}
        <div className="hidden md:flex items-center gap-3">
          <TraderSearch />
          <button
            onClick={() => navigate("/dashboard")}
            className="px-4 py-2 text-sm font-semibold bg-[#00FF66] text-black rounded-lg hover:bg-[#00FF66]/90 transition-all duration-200 shadow-neon"
          >
            Launch Dashboard
          </button>
        </div>
      </div>
    </motion.nav>
  );
}
